"""Names of zlib, OpenSSL and musl libc code, for the static musl OpenSSH recipes.

GENERATED by exercisers/openssh_musl_symbols.py; do not edit. Taken from OpenSSH 9.6p1 and 10.6p2 as built by the OpenSSH_*_musl recipes (x64 and x86): zlib 1.3.1 libz.a, OpenSSL 3.0.15 libcrypto.a and libssl.a, and the libc.a of the pinned musl.cc toolchains (musl 1.2.2-git-50-gb76f37fd). Regenerate when the pins change.

EXACT[label] is every function symbol defined by the pinned static
archive(s) of that label (union over the architectures and releases built)
that no OpenSSH object defines. COLLISIONS[label] is the library names that
OpenSSH's own objects also define; they are not excluded.

zlib       130 exact names,   6 collisions left out
openssl  12166 exact names,  10 collisions left out
libc      2211 exact names,  10 collisions left out
"""

import re


def _trie(names):
    """A regular expression matching exactly ``names`` (a character trie)."""
    root = {}
    for name in names:
        node = root
        for char in name:
            node = node.setdefault(char, {})
        node[""] = {}

    def render(node):
        if list(node) == [""]:
            return ""
        parts = []
        end = "" in node
        for char in sorted(k for k in node if k):
            parts.append(re.escape(char) + render(node[char]))
        body = parts[0] if len(parts) == 1 else "(?:" + "|".join(parts) + ")"
        return "(?:" + body + ")?" if end else body

    return "^" + render(root) + "$"


